    margin: 0;
    letter-spacing: -0.5px;
}

.header__nav {
    flex: 1;
    text-align: center;
    display: none;
}

@media (min-width: 768px) {
    .header__nav {
        display: block;
    }
}

.nav__list {
    list-style: none;
