    gap: var(--spacing-lg);
    justify-content: center;
}

.nav__link {
    color: white;
    font-weight: 500;
    transition: color var(--transition-fast);
}

.nav__link:hover {
    color: var(--color-accent-light);
}

.header__cart {
    background: none;
    border: none;
    color: white;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    font-size: var(--font-size-lg);
    transition: color var(--transition-fast);
    padding: var(--spacing-sm);
    border-radius: var(--border-radius-md);
}

.header__cart:hover {
    color: var(--color-accent-light);
}

/* ============================================
   HERO SECTION
   ============================================ */

.hero {
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
    color: white;
    padding: var(--spacing-3xl) var(--spacing-md);
    text-align: center;
    min-height: 500px;
    display: flex;
    align-items: center;
