    --transition-fast: 150ms ease-in-out;
    --transition-base: 250ms ease-in-out;
    --transition-slow: 350ms ease-in-out;
}

/* ============================================
   RESET & BASE STYLES
   ============================================ */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-family-base);
    font-size: var(--font-size-base);
    line-height: 1.6;
    color: var(--color-neutral-700);
    background-color: #ffffff;
}

/* ============================================
   ACCESSIBILITY
   ============================================ */

.skip-to-main {
    position: absolute;
    top: -9999px;
    left: -9999px;
    z-index: 999;
}

.skip-to-main:focus {
    top: var(--spacing-md);
    left: var(--spacing-md);
    padding: var(--spacing-md);
    background-color: var(--color-primary);
    color: white;
    border-radius: var(--border-radius-md);
    text-decoration: none;
    outline: 3px solid var(--color-accent);
}

button, a {
    outline-offset: 2px;
}

button:focus-visible, a:focus-visible {
    outline: 3px solid var(--color-accent);
    outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
    * {
        animation: none !important;
        transition: none !important;
    }
}

/* ============================================
   TYPOGRAPHY
   ============================================ */

h1, h2, h3, h4, h5, h6 {
    font-weight: 600;
    line-height: 1.3;
    color: var(--color-primary);
}

h1 {
    font-size: var(--font-size-4xl);
}

h2 {
    font-size: var(--font-size-3xl);
    margin-bottom: var(--spacing-md);
}

h3 {
    font-size: var(--font-size-xl);
}

a {
    color: var(--color-secondary);
    text-decoration: none;
    transition: color var(--transition-fast);
}

a:hover {
    color: var(--color-accent);
}

a:visited {
    color: var(--color-secondary);
}

/* ============================================
   CONTAINER & LAYOUT
   ============================================ */

.container {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

@media (min-width: 768px) {
    .container {
        padding: 0 var(--spacing-lg);
    }
}

/* ============================================
   HEADER & NAVIGATION
   ============================================ */

.header {
    background-color: var(--color-primary);
    color: white;
    padding: var(--spacing-md) 0;
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: var(--shadow-md);
}

.header__container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

@media (min-width: 768px) {
    .header__container {
        padding: 0 var(--spacing-lg);
    }
}

.header__logo {
    flex: 1;
}

.logo__text {
    font-size: var(--font-size-2xl);
    font-weight: 700;
    margin: 0;
    letter-spacing: -0.5px;
}

.header__nav {
    flex: 1;
    text-align: center;
    display: none;
}

@media (min-width: 768px) {
    .header__nav {
        display: block;
    }
}

.nav__list {
    list-style: none;
    display: flex;
    gap: var(--spacing-lg);
    justify-content: center;
}

.nav__link {
    color: white;
    font-weight: 500;
    transition: color var(--transition-fast);
}

.nav__link:hover {
    color: var(--color-accent-light);
}

.header__cart {
    background: none;
    border: none;
    color: white;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    font-size: var(--font-size-lg);
    transition: color var(--transition-fast);
    padding: var(--spacing-sm);
    border-radius: var(--border-radius-md);
}

.header__cart:hover {
    color: var(--color-accent-light);
}

/* ============================================
   HERO SECTION
   ============================================ */

.hero {
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
    color: white;
    padding: var(--spacing-3xl) var(--spacing-md);
    text-align: center;
    min-height: 500px;
    display: flex;
    align-items: center;
    justify-content: center;
}

@media (min-width: 768px) {
    .hero {
        padding: var(--spacing-3xl) var(--spacing-lg);
        min-height: 600px;
    }
}

.hero__content {
    max-width: 600px;
}

.hero__title {
    font-size: var(--font-size-4xl);
    color: white;
    margin-bottom: var(--spacing-lg);
    font-weight: 700;
}

@media (min-width: 768px) {
    .hero__title {
        font-size: 3.5rem;
    }
}

.hero__subtitle {
    font-size: var(--font-size-xl);
    margin-bottom: var(--spacing-xl);
    opacity: 0.95;
    line-height: 1.5;
}

/* ============================================
   BUTTONS
   ============================================ */

.button {
    display: inline-block;
    padding: var(--spacing-md) var(--spacing-xl);
    border: none;
    border-radius: var(--border-radius-md);
    font-size: var(--font-size-base);
    font-weight: 600;
    cursor: pointer;
    transition: all var(--transition-fast);
    text-decoration: none;
    white-space: nowrap;
}

.button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.button--primary {
    background-color: var(--color-accent);
    color: white;
}

.button--primary:hover:not(:disabled) {
    background-color: var(--color-accent-light);
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
}

.button--secondary {
    background-color: var(--color-neutral-200);
    color: var(--color-primary);
    border: 2px solid transparent;
}

.button--secondary:hover:not(:disabled) {
    background-color: var(--color-neutral-300);
    border-color: var(--color-accent);
}

.button--link {
    background: none;
    color: var(--color-accent);
    padding: 0;
    font-weight: 600;
}

.button--link:hover {
    color: var(--color-accent-light);
    text-decoration: underline;
}

/* ============================================
   SECTION STYLES
   ============================================ */

section {
    padding: var(--spacing-3xl) var(--spacing-md);
}

@media (min-width: 768px) {
    section {
        padding: var(--spacing-3xl) var(--spacing-lg);
    }
}

.section__title {
    text-align: center;
    margin-bottom: var(--spacing-md);
    position: relative;
}

.section__title::after {
    content: '';
    display: block;
    width: 60px;
    height: 4px;
    background: linear-gradient(90deg, var(--color-accent), var(--color-accent-light));
    margin: var(--spacing-md) auto 0;
    border-radius: 2px;
}

.section__description {
    text-align: center;
    color: var(--color-neutral-600);
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-2xl);
}

.section__cta {
    text-align: center;
    margin-top: var(--spacing-2xl);
}

/* ============================================
   PRODUCTS GRID
   ============================================ */

.featured {
    background-color: var(--color-neutral-50);
}

.products__grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-2xl);
}

@media (min-width: 768px) {
    .products__grid {
        grid-template-columns: repeat(4, 1fr);
        gap: var(--spacing-lg);
    }
}

@media (min-width: 1024px) {
    .products__grid {
        grid-template-columns: repeat(4, 1fr);
    }
}

/* ============================================
   PRODUCT CARD
   ============================================ */

.product-card {
    background: white;
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-md);
    transition: all var(--transition-base);
    display: flex;
    flex-direction: column;
    height: 100%;
}

.product-card:hover {
    box-shadow: var(--shadow-xl);
    transform: translateY(-4px);
}

.product-card__image {
    position: relative;
    width: 100%;
    padding-bottom: 100%;
    overflow: hidden;
    background-color: var(--color-neutral-100);
}

.product-card__image img {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-base);
}

.product-card:hover .product-card__image img {
    transform: scale(1.05);
}

.product-card__badge {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    background-color: var(--color-accent);
    color: white;
    padding: var(--spacing-xs) var(--spacing-md);
    border-radius: var(--border-radius-md);
    font-size: var(--font-size-xs);
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    z-index: 10;
}

.product-card__content {
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
    flex: 1;
}

.product-card__title {
    font-size: var(--font-size-lg);
    font-weight: 600;
    color: var(--color-primary);
    margin-bottom: var(--spacing-sm);
}

.product-card__description {
    font-size: var(--font-size-sm);
    color: var(--color-neutral-600);
    margin-bottom: var(--spacing-lg);
    flex: 1;
}

.product-card__price {
    font-size: var(--font-size-2xl);
    font-weight: 700;
    color: var(--color-accent);
    margin-bottom: var(--spacing-lg);
}

.product-card .button {
    width: 100%;
    justify-content: center;
}

/* ============================================
   DEALS SECTION
   ============================================ */

.deals {
    background-color: white;
}

.deals__grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-xl);
}

/* ============================================
   DEAL CARD
   ============================================ */

.deal-card {
    background: linear-gradient(135deg, var(--color-secondary) 0%, #164e63 100%);
    color: white;
    padding: var(--spacing-xl);
    border-radius: var(--border-radius-lg);
    box-shadow: var(--shadow-md);
    transition: all var(--transition-base);
}

.deal-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-xl);
}

.deal-card__header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: var(--spacing-lg);
}

.deal-card__title {
    font-size: var(--font-size-xl);
    font-weight: 700;
    margin: 0;
    color: white;
}

.deal-card__discount {
    background-color: var(--color-accent);
    color: white;
    padding: var(--spacing-sm) var(--spacing-md);
    border-radius: var(--border-radius-md);
    font-weight: 700;
    font-size: var(--font-size-sm);
    white-space: nowrap;
}

.deal-card__description {
    font-size: var(--font-size-base);
    margin-bottom: var(--spacing-lg);
    opacity: 0.9;
}

.deal-card__timer {
    display: flex;
    gap: var(--spacing-md);
    margin-bottom: var(--spacing-lg);
    font-weight: 500;
}

.timer-label {
    opacity: 0.85;
}

.timer-value {
    font-weight: 700;
    font-size: var(--font-size-lg);
}

/* ============================================
   EDITORIAL SECTION
   ============================================ */

.editorial {
    background-color: var(--color-neutral-50);
}

.editorial__grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-xl);
}

/* ============================================
   EDITORIAL CARD
   ============================================ */

.editorial-card {
    background: white;
    border-radius: var(--border-radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-md);
    transition: all var(--transition-base);
    display: flex;
    flex-direction: column;
    height: 100%;
}

.editorial-card:hover {
    box-shadow: var(--shadow-xl);
    transform: translateY(-4px);
}

.editorial-card__image {
    width: 100%;
    padding-bottom: 62.5%;
    overflow: hidden;
    background-color: var(--color-neutral-200);
}

.editorial-card__image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform var(--transition-base);
}

.editorial-card:hover .editorial-card__image img {
    transform: scale(1.05);
}

.editorial-card__content {
    padding: var(--spacing-lg);
    display: flex;
    flex-direction: column;
    flex: 1;
}

.editorial-card__category {
    display: inline-block;
    background-color: var(--color-accent);
    color: white;
    padding: var(--spacing-xs) var(--spacing-md);
    border-radius: var(--border-radius-sm);
    font-size: var(--font-size-xs);
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: var(--spacing-md);
    width: fit-content;
}

.editorial-card__title {
    font-size: var(--font-size-lg);
    font-weight: 600;
    color: var(--color-primary);
    margin-bottom: var(--spacing-md);
    line-height: 1.4;
}

.editorial-card__excerpt {
    font-size: var(--font-size-sm);
    color: var(--color-neutral-600);
    margin-bottom: var(--spacing-md);
    flex: 1;
    line-height: 1.6;
}

.editorial-card__date {
    display: block;
    font-size: var(--font-size-xs);
    color: var(--color-neutral-500);
    margin-bottom: var(--spacing-md);
}

.editorial-card__link {
    color: var(--color-accent);
    font-weight: 600;
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-sm);
    transition: all var(--transition-fast);
}

.editorial-card__link:hover {
    color: var(--color-accent-light);
    transform: translateX(2px);
}

/* ============================================
   NEWSLETTER SECTION
   ============================================ */

.newsletter {
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-secondary) 100%);
    color: white;
    text-align: center;
}

.newsletter__title {
    color: white;
    margin-bottom: var(--spacing-md);
}

.newsletter__subtitle {
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-xl);
    opacity: 0.95;
}

.newsletter__form {
    max-width: 500px;
    margin: 0 auto;
    display: flex;
    gap: var(--spacing-md);
    flex-direction: column;
}

@media (min-width: 768px) {
    .newsletter__form {
        flex-direction: row;
    }
}

.form__group {
    flex: 1;
    text-align: left;
}

.form__label {
    display: block;
    margin-bottom: var(--spacing-sm);
    font-weight: 600;
    font-size: var(--font-size-sm);
}

.form__input {
    width: 100%;
    padding: var(--spacing-md) var(--spacing-lg);
    border: none;
    border-radius: var(--border-radius-md);
    font-size: var(--font-size-base);
    transition: all var(--transition-fast);
}

.form__input:focus {
    outline: 3px solid var(--color-accent);
    outline-offset: 2px;
}

.form__input::placeholder {
    color: var(--color-neutral-400);
}

.newsletter__form .button {
    align-self: flex-start;
}

@media (min-width: 768px) {
    .newsletter__form .button {
        align-self: flex-end;
    }
}

/* ============================================
   FOOTER
   ============================================ */

.footer {
    background-color: var(--color-primary);
    color: var(--color-neutral-300);
    padding: var(--spacing-3xl) var(--spacing-md) var(--spacing-xl);
}

@media (min-width: 768px) {
    .footer {
        padding: var(--spacing-3xl) var(--spacing-lg) var(--spacing-xl);
    }
}

.footer__grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-2xl);
    margin-bottom: var(--spacing-2xl);
    max-width: 1200px;
    margin-left: auto;
    margin-right: auto;
}

.footer__nav,
.footer__info {
    text-align: left;
}

.footer__heading {
    font-size: var(--font-size-lg);
    font-weight: 700;
    color: white;
    margin-bottom: var(--spacing-lg);
}

.footer__list {
    list-style: none;
}

.footer__list li {
    margin-bottom: var(--spacing-md);
}

.footer__list a {
    color: var(--color-neutral-300);
    transition: color var(--transition-fast);
}

.footer__list a:hover {
    color: var(--color-accent-light);
}

.footer__bottom {
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    padding-top: var(--spacing-xl);
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
    font-size: var(--font-size-sm);
    max-width: 1200px;
    margin: 0 auto;
}

@media (min-width: 768px) {
    .footer__bottom {
        flex-direction: row;
        justify-content: space-between;
        align-items: center;
    }
}

.footer__links {
    display: flex;
    gap: var(--spacing-xl);
    flex-wrap: wrap;
}

.footer__links a {
    color: var(--color-neutral-300);
    transition: color var(--transition-fast);
}

.footer__links a:hover {
    color: var(--color-accent-light);
}

/* ============================================
   RESPONSIVE
   ============================================ */

@media (max-width: 767px) {
    .products__grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .editorial__grid {
        grid-template-columns: 1fr;
    }

    h1 {
        font-size: var(--font-size-3xl);
    }

    .hero {
        min-height: 400px;
        padding: var(--spacing-2xl) var(--spacing-md);
    }

    .hero__title {
        font-size: var(--font-size-3xl);
    }

    .hero__subtitle {
        font-size: var(--font-size-base);
    }
}

