/* ============================================
   ACCESSIBILITY
   ============================================ */

.skip-to-main {
    position: absolute;
    top: -9999px;
    left: -9999px;
    z-index: 999;
}

.skip-to-main:focus {
    top: var(--spacing-md);
    left: var(--spacing-md);
    padding: var(--spacing-md);
    background-color: var(--color-primary);
    color: white;
    border-radius: var(--border-radius-md);
    text-decoration: none;
    outline: 3px solid var(--color-accent);
}

button, a {
