            notification.classList.remove('notification--show');
            setTimeout(() => notification.remove(), 300);
        }, 3000);
    }
}

// ============================================
// PRODUCT INTERACTIONS
// ============================================

function initializeProductCards() {
    const productButtons = document.querySelectorAll('.product-card .button--secondary');

    productButtons.forEach((button) => {
        button.addEventListener('click', (e) => {
            e.preventDefault();

            const productCard = button.closest('.product-card');
            const title = productCard.querySelector('.product-card__title').textContent;
            const priceText = productCard.querySelector('.product-card__price').textContent;
            const price = parseFloat(priceText.replace('$', ''));

            const product = {
                id: Math.random().toString(36).substr(2, 9),
                name: title,
                price: price,
                image: productCard.querySelector('.product-card__image img').src
            };

            cart.addItem(product);
        });
    });
}

// ============================================
// NEWSLETTER SUBSCRIPTION
// ============================================

function initializeNewsletter() {
    const form = document.querySelector('.newsletter__form');
    if (!form) return;

    form.addEventListener('submit', (e) => {
        e.preventDefault();
        const emailInput = form.querySelector('#email');
        const email = emailInput.value;

        if (validateEmail(email)) {
            localStorage.setItem('newsletter_email', email);
            cart.showNotification(`Welcome! Check ${email} for exclusive offers`);
            emailInput.value = '';
            emailInput.focus();
        } else {
            showError(emailInput, 'Please enter a valid email address');
        }
    });
}

function validateEmail(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function showError(element, message) {
    const errorId = `error-${element.id}`;
    let errorElement = document.getElementById(errorId);

    if (!errorElement) {
        errorElement = document.createElement('div');
        errorElement.id = errorId;
        errorElement.className = 'form-error';
        errorElement.setAttribute('role', 'alert');
        element.after(errorElement);
    }

    errorElement.textContent = message;
    element.setAttribute('aria-invalid', 'true');
    element.setAttribute('aria-describedby', errorId);

    setTimeout(() => {
        if (validateEmail(element.value)) {
            errorElement.remove();
            element.setAttribute('aria-invalid', 'false');
            element.removeAttribute('aria-describedby');
        }
    }, 3000);
}

// ============================================
// DEAL TIMERS
// ============================================

function initializeDealTimers() {
    const timers = document.querySelectorAll('.deal-card__timer');

    timers.forEach((timer) => {
        const valueElement = timer.querySelector('.timer-value');
        if (!valueElement) return;

        const initialText = valueElement.textContent;

        if (initialText !== 'All Month') {
            let timeRemaining = parseTimeToSeconds(initialText);

            setInterval(() => {
                timeRemaining--;
                if (timeRemaining >= 0) {
                    valueElement.textContent = formatTime(timeRemaining);
                }
            }, 1000);
        }
    });
}

function parseTimeToSeconds(timeString) {
    const parts = timeString.match(/(\d+)([hd])/g) || [];
    let seconds = 0;

    parts.forEach((part) => {
        const value = parseInt(part);
        if (part.includes('h')) seconds += value * 3600;
        if (part.includes('d')) seconds += value * 86400;
    });

    return seconds;
}

function formatTime(seconds) {
    const days = Math.floor(seconds / 86400);
    const hours = Math.floor((seconds % 86400) / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);

    if (days > 0) {
        return `${days}d ${hours}h`;
    } else if (hours > 0) {
        return `${hours}h ${minutes}m`;
    } else {
        return `${minutes}m`;
    }
}

// ============================================
// SMOOTH SCROLLING
// ============================================

function initializeSmoothScroll() {
    document.querySelectorAll('a[href^="#"]').forEach((anchor) => {
        anchor.addEventListener('click', function (e) {
            const href = this.getAttribute('href');
            if (href === '#' || href === '#main-content') return;

            const target = document.querySelector(href);
            if (target) {
                e.preventDefault();
                target.scrollIntoView({ behavior: 'smooth' });
                target.focus();
            }
        });
    });
}

