                max-width: none;
            }
        }
    `;
    document.head.appendChild(style);
}

// ============================================
// DEAL BUTTON INTERACTIONS
// ============================================

function initializeDealButtons() {
    const dealButtons = document.querySelectorAll('.deals__grid .button--secondary');

    dealButtons.forEach((button) => {
        button.addEventListener('click', (e) => {
            e.preventDefault();
            const dealCard = button.closest('.deal-card');
            const title = dealCard.querySelector('.deal-card__title').textContent;
            const discount = dealCard.querySelector('.deal-card__discount').textContent;

            cart.showNotification(`Applied: ${title} - ${discount}`);
        });
    });
}

// ============================================
// INITIALIZATION
// ============================================

document.addEventListener('DOMContentLoaded', () => {
    injectNotificationStyles();

    // Initialize cart (global instance)
    window.cart = new Cart();

    // Initialize all components
    initializeProductCards();
    initializeNewsletter();
    initializeDealTimers();
    initializeDealButtons();
    initializeSmoothScroll();

    // Add keyboard navigation for main nav
    const navLinks = document.querySelectorAll('.nav__link');
    navLinks.forEach((link, index) => {
        link.addEventListener('keydown', (e) => {
            if (e.key === 'ArrowRight' && index < navLinks.length - 1) {
                navLinks[index + 1].focus();
            } else if (e.key === 'ArrowLeft' && index > 0) {
                navLinks[index - 1].focus();
            }
        });
    });
});

// ============================================
// UTILITIES
// ============================================

// Intersection Observer for lazy animations
function initializeLazyAnimations() {
    if (!('IntersectionObserver' in window)) return;

    const observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                entry.target.classList.add('in-view');
                observer.unobserve(entry.target);
            }
        });
    }, { threshold: 0.1 });

    document.querySelectorAll('.product-card, .deal-card, .editorial-card').forEach((el) => {
        observer.observe(el);
    });
}

// Run animations after DOM content loads
document.addEventListener('DOMContentLoaded', () => {
    initializeLazyAnimations();
});
